class Solution {
public:
    int maxArea(vector<int>& height) {
        int left = 0, right = (int)height.size() - 1;
        int max_a = 0;
        while (left < right) {
            int h = min(height[left], height[right]);
            max_a = max(max_a, h * (right - left));
            if (height[left] < height[right]) left++;
            else right--;
        }
        return max_a;
    }
};

